<style>
@font-face{font-family:"EC916 Sans";src:url("/theme-demo/ec916/fonts/BeVietnamPro-Regular.ttf") format("truetype");font-weight:400;font-display:swap}
@font-face{font-family:"EC916 Sans";src:url("/theme-demo/ec916/fonts/BeVietnamPro-SemiBold.ttf") format("truetype");font-weight:600;font-display:swap}
@font-face{font-family:"EC916 Sans";src:url("/theme-demo/ec916/fonts/BeVietnamPro-Bold.ttf") format("truetype");font-weight:700;font-display:swap}
:root{--ec16-navy:#15394b;--ec16-deep:#0f2f3f;--ec16-teal:#16b6a3;--ec16-cyan:#61cbe3;--ec16-orange:#ff6c35;--ec16-red:#ef2435;--ec16-pink:#ff68b5;--ec16-paper:#f5f6f7;--ec16-ink:#17212a;--ec16-muted:#71808b;--ec16-shadow:0 10px 28px rgba(13,47,63,.12)}
*{box-sizing:border-box}.ec16-page{font-family:"EC916 Sans",Arial,sans-serif;color:var(--ec16-ink);background:#fff}.ec16-page a{color:inherit;text-decoration:none}.ec16-page img{display:block;max-width:100%}.ec16-container{width:min(1500px,calc(100% - 40px));margin:auto}
.ec16-header{position:relative;z-index:60;background:var(--ec16-navy);color:#fff;border-top:3px solid var(--ec16-teal)}.ec16-header-main{height:104px;display:flex;align-items:center;gap:28px}.ec16-logo{display:flex;align-items:center;gap:12px;min-width:275px}.ec16-logo img{max-width:250px;max-height:70px}.ec16-logo>i{font-size:48px;color:var(--ec16-orange);transform:skew(-8deg)}.ec16-logo span{font-size:24px;font-weight:700;line-height:1.05}.ec16-logo b{display:block;font-size:34px;letter-spacing:2px}.ec16-search{height:50px;display:flex;flex:1;max-width:720px;background:#fff;border-radius:6px;overflow:hidden}.ec16-search select{border:0;border-right:1px solid #ddd;padding:0 16px;color:#555}.ec16-search input{border:0;outline:0;flex:1;padding:0 20px;font:inherit}.ec16-search button{width:58px;border:0;background:var(--ec16-orange);color:#fff;font-size:20px}.ec16-account{display:flex;align-items:center;gap:12px;border:0;background:transparent;color:#fff;text-align:left;font:inherit}.ec16-account>i{font-size:31px}.ec16-account b,.ec16-account small{display:block}.ec16-cart{width:58px;height:52px;border-radius:6px;background:var(--ec16-orange);display:grid;place-items:center;position:relative;font-size:20px}.ec16-cart em{position:absolute;right:-12px;top:-12px;width:34px;height:24px;border-radius:14px;background:#0987cd;font-size:13px;display:grid;place-items:center;font-style:normal}.ec16-menu-toggle{display:none;border:0;background:transparent;color:#fff;font-size:24px}.ec16-benefits{margin-top:-27px;padding-bottom:15px}.ec16-benefits .ec16-container{display:flex;justify-content:center;gap:90px;font-size:13px}.ec16-benefits i{margin-right:6px}.ec16-header nav{border-top:1px solid rgba(255,255,255,.08);background:var(--ec16-deep)}.ec16-header nav>.ec16-container{height:56px;display:flex;align-items:center;justify-content:center;gap:44px}.ec16-header nav a{font-size:14px;font-weight:600;white-space:nowrap}.ec16-header nav a:hover{color:var(--ec16-orange)}.ec16-mega-trigger{height:100%;display:flex;align-items:center;position:relative}.ec16-mega{position:absolute;top:56px;left:50%;transform:translateX(-50%) translateY(10px);width:min(1120px,92vw);background:#fff;color:#333;display:grid;grid-template-columns:repeat(4,1fr);gap:35px;padding:35px;box-shadow:var(--ec16-shadow);opacity:0;visibility:hidden;transition:.25s;border-top:4px solid var(--ec16-orange)}.ec16-mega-trigger:hover .ec16-mega{opacity:1;visibility:visible;transform:translateX(-50%) translateY(0)}.ec16-mega section>*{display:block;margin:10px 0}.ec16-mega section b{font-size:17px}
.ec16-hero{height:620px}.ec16-hero>div,.ec16-hero article{height:100%;position:relative;overflow:hidden}.ec16-hero article{position:absolute;inset:0;opacity:0;transition:opacity .65s}.ec16-hero article.is-active{opacity:1}.ec16-hero img{width:100%;height:100%;object-fit:cover}.ec16-hero-copy{position:absolute;left:max(6vw,40px);top:50%;transform:translateY(-50%);width:42%;color:#fff}.ec16-hero-copy span{color:#8ff2e4;font-weight:700;letter-spacing:3px}.ec16-hero-copy h1{font-size:clamp(42px,5vw,72px);line-height:1.08;margin:18px 0}.ec16-hero-copy p{font-size:17px;line-height:1.65}.ec16-hero-copy a{display:inline-flex;gap:10px;align-items:center;margin-top:22px;padding:14px 25px;border:2px solid #fff;border-radius:5px;font-weight:700;text-transform:uppercase}.ec16-hero button[data-ec16-prev],.ec16-hero button[data-ec16-next]{position:absolute;z-index:4;top:50%;width:42px;height:48px;border:0;background:rgba(255,255,255,.85);color:var(--ec16-navy)}.ec16-hero .prev{left:14px}.ec16-hero .next{right:14px}
.ec16-section{padding:76px 0}.ec16-heading{text-align:center;margin-bottom:38px}.ec16-heading span{color:var(--ec16-teal);font-weight:700;letter-spacing:3px}.ec16-heading h2{font-size:38px;margin:12px 0}.ec16-categories{background:var(--ec16-paper)}.ec16-category-grid{display:grid;grid-template-columns:repeat(8,1fr);gap:18px}.ec16-category-grid a{background:#fff;border-radius:12px;text-align:center;padding:17px 10px;box-shadow:0 5px 15px rgba(0,0,0,.04);transition:.3s}.ec16-category-grid a:hover{transform:translateY(-6px);box-shadow:var(--ec16-shadow)}.ec16-category-grid img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:50%;margin-bottom:12px}.ec16-category-grid b,.ec16-category-grid small{display:block}.ec16-category-grid small{color:var(--ec16-muted);margin-top:5px;font-size:12px}
.ec16-products-section{background:#f2f2f2}.ec16-section-bar{display:flex;align-items:center;border-bottom:1px solid #ccc;margin-bottom:25px}.ec16-section-bar h2{font-size:23px;text-transform:uppercase;border-bottom:3px solid var(--ec16-orange);padding:0 0 14px;margin:0}.ec16-section-bar>a,.ec16-section-bar>span{margin-left:auto;color:#666}.ec16-section-bar.pink{border-top:2px solid var(--ec16-pink);background:#fff;padding-right:22px}.ec16-section-bar.pink h2{background:var(--ec16-pink);color:#fff;padding:14px 24px;border:0}.ec16-product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:26px}.ec16-product{background:#fff;transition:.3s;position:relative}.ec16-product:hover{transform:translateY(-6px);box-shadow:var(--ec16-shadow)}.ec16-product-image{display:block;position:relative;aspect-ratio:1;overflow:hidden}.ec16-product-image img{width:100%;height:100%;object-fit:cover;transition:.4s}.ec16-product:hover img{transform:scale(1.04)}.ec16-product-image span{position:absolute;left:13px;top:13px;background:var(--ec16-red);color:#fff;border-radius:18px;padding:5px 10px}.ec16-product>div{padding:15px 18px 18px}.ec16-product h3{font-size:16px;line-height:1.5;min-height:50px}.ec16-product p{display:flex;align-items:center;gap:13px}.ec16-product strong{font-size:22px;color:var(--ec16-red)}.ec16-product del{color:#aaa}.ec16-product small{display:block;text-align:right;color:#999}
.ec16-promo-pair .ec16-container{display:grid;grid-template-columns:1fr 1fr;gap:34px}.ec16-promo-pair a{height:330px;position:relative;overflow:hidden}.ec16-promo-pair img{width:100%;height:100%;object-fit:cover;transition:.5s}.ec16-promo-pair a:hover img{transform:scale(1.04)}.ec16-promo-pair span{position:absolute;left:38px;top:50%;transform:translateY(-50%);width:46%;display:flex;flex-direction:column;align-items:flex-start}.ec16-promo-pair small{color:var(--ec16-orange);font-weight:700}.ec16-promo-pair b{font-size:29px;line-height:1.2;margin:8px 0}.ec16-promo-pair em{font-style:normal}.ec16-promo-pair strong{margin-top:18px;background:var(--ec16-orange);color:#fff;padding:10px 18px;border-radius:4px}.ec16-beauty{padding-top:45px}
.ec16-campaign-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;grid-template-rows:260px 260px;gap:24px}.ec16-campaign-grid a{position:relative;overflow:hidden}.ec16-campaign-grid .item-1{grid-row:span 2}.ec16-campaign-grid img{width:100%;height:100%;object-fit:cover;transition:.5s}.ec16-campaign-grid a:hover img{transform:scale(1.04)}.ec16-campaign-grid span{position:absolute;inset:auto 0 0;padding:55px 25px 20px;color:#fff;background:linear-gradient(transparent,rgba(8,28,39,.8))}.ec16-campaign-grid span>*{display:block}.ec16-campaign-grid small{color:#83f3e4;font-weight:700}.ec16-campaign-grid b{font-size:24px;margin:5px 0}.ec16-campaign-grid em{font-style:normal}
.ec16-brands{background:var(--ec16-paper)}.ec16-brand-row{display:grid;grid-template-columns:repeat(8,1fr);gap:18px}.ec16-brand-row span{height:86px;background:#fff;display:grid;place-items:center;border-radius:10px;color:var(--ec16-navy);font-size:19px;font-weight:700;font-style:italic;box-shadow:0 4px 12px rgba(0,0,0,.04)}.ec16-newsletter{background:var(--ec16-cyan);color:#fff;padding:25px 0}.ec16-newsletter .ec16-container{display:grid;grid-template-columns:1fr 1.2fr;gap:50px;align-items:center}.ec16-newsletter h2{font-size:25px;text-transform:uppercase;margin:0}.ec16-newsletter p{font-style:italic;margin:5px 0 0}.ec16-newsletter form{height:58px;display:flex;background:#fff;border-radius:5px;overflow:hidden}.ec16-newsletter input{border:0;outline:0;flex:1;padding:0 25px;font:inherit}.ec16-newsletter button{width:78px;border:0;background:var(--ec16-orange);color:#fff;font-size:22px}.ec16-footer{background:var(--ec16-navy);color:#c8e7f0;padding-top:58px}.ec16-footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:60px}.ec16-footer h3{color:#fff;text-transform:uppercase}.ec16-footer a{display:block;margin:14px 0}.ec16-footer p{display:flex;gap:12px;line-height:1.6}.ec16-footer p i{color:var(--ec16-orange);margin-top:5px}.ec16-copyright{text-align:center;border-top:1px solid rgba(255,255,255,.1);margin-top:45px;padding:20px;color:#789eae}
.ec16-content{padding:70px 0}.ec16-listing{display:grid;grid-template-columns:repeat(4,1fr);gap:25px}.ec16-button{border:0;background:var(--ec16-orange);color:#fff;padding:13px 22px;border-radius:5px}.ec16-product-detail{display:grid;grid-template-columns:1fr 1fr;gap:60px}.ec16-product-detail>div:first-child img{width:100%;max-height:680px;object-fit:contain}.ec16-product-detail strong{font-size:32px;color:var(--ec16-red)}
.ec16-motion-ready [data-ec16-reveal],.ec16-motion-ready [data-ec16-motion],.ec16-motion-ready [data-ec16-stagger]{opacity:0;will-change:transform,opacity}.ec16-motion-ready [data-ec16-reveal]{transform:translateY(58px);transition:opacity .75s ease,transform .85s cubic-bezier(.2,.75,.2,1)}.ec16-motion-ready [data-ec16-motion="left"]{transform:translateX(-70px);transition:opacity .8s ease,transform .9s cubic-bezier(.2,.75,.2,1)}.ec16-motion-ready [data-ec16-motion="right"]{transform:translateX(70px);transition:opacity .8s ease,transform .9s cubic-bezier(.2,.75,.2,1)}.ec16-motion-ready [data-ec16-motion="scale"]{transform:scale(.92);transition:opacity .7s ease,transform .85s cubic-bezier(.2,.75,.2,1)}.ec16-motion-ready [data-ec16-stagger]{transform:translateY(38px);transition:opacity .6s ease,transform .7s cubic-bezier(.2,.75,.2,1);transition-delay:var(--ec16-delay,0ms)}.ec16-motion-ready [data-ec16-reveal].is-visible,.ec16-motion-ready [data-ec16-motion].is-visible,.ec16-motion-ready [data-ec16-stagger].is-visible{opacity:1;transform:none}.ec16-motion-ready [data-ec16-reveal].is-visible [data-ec16-motion],.ec16-motion-ready [data-ec16-reveal].is-visible [data-ec16-stagger]{opacity:1;transform:none}
@media(max-width:1100px){.ec16-logo{min-width:auto}.ec16-account span{display:none}.ec16-header nav>.ec16-container{gap:22px;overflow-x:auto;justify-content:flex-start}.ec16-category-grid{grid-template-columns:repeat(4,1fr)}.ec16-product-grid{grid-template-columns:repeat(3,1fr)}.ec16-campaign-grid{grid-template-columns:1fr 1fr}.ec16-campaign-grid .item-1{grid-row:auto}.ec16-footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:760px){.ec16-header-main{height:78px}.ec16-logo span{font-size:16px}.ec16-logo b{font-size:22px}.ec16-logo>i{font-size:32px}.ec16-search,.ec16-account,.ec16-benefits{display:none}.ec16-cart{margin-left:auto}.ec16-menu-toggle{display:block}.ec16-header nav{display:none}.ec16-header nav.is-open{display:block}.ec16-header nav>.ec16-container{height:auto;display:grid;padding:15px 20px}.ec16-mega{display:none}.ec16-hero{height:520px}.ec16-hero img{object-position:62% center}.ec16-hero-copy{left:25px;width:82%}.ec16-hero-copy h1{font-size:38px}.ec16-section{padding:52px 0}.ec16-category-grid{grid-template-columns:repeat(2,1fr)}.ec16-product-grid{grid-template-columns:repeat(2,1fr);gap:12px}.ec16-section-bar>span{display:none}.ec16-product>div{padding:10px}.ec16-product strong{font-size:17px}.ec16-promo-pair .ec16-container,.ec16-newsletter .ec16-container,.ec16-product-detail{grid-template-columns:1fr}.ec16-promo-pair a{height:270px}.ec16-promo-pair span{left:20px;width:54%}.ec16-campaign-grid{display:grid;grid-template-columns:1fr;grid-template-rows:auto}.ec16-campaign-grid a{height:270px}.ec16-brand-row{grid-template-columns:repeat(2,1fr)}.ec16-newsletter h2{font-size:20px}.ec16-footer-grid{grid-template-columns:1fr}.ec16-listing{grid-template-columns:repeat(2,1fr)}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
</style>
